function ichefFiscalId(prefix = 'FISCAL') {
return (
prefix +
'_' +
Date.now() +
'_' +
nodeCrypto.randomBytes(8).toString('hex')
);
}
async function ichefWriteFiscalRecord(data = {}) {
const tenantID = cleanString(data.tenantID);
if (!tenantID) {
return null;
}
const recordId =
String(
data.recordId ||
data.operationId ||
data.ticketNumber ||
ichefFiscalId(data.type || 'EVENT')
);
const record = {
tenantID,
recordId,
type:
String(data.type || 'EVENT')
.trim()
.toUpperCase(),
subtype:
String(data.subtype || ''),
tableId:
String(data.tableId || ''),
ticketNumber:
String(data.ticketNumber || ''),
operationId:
String(data.operationId || ''),
status:
String(data.status || ''),
amount:
Number(data.amount || 0),
currency:
String(data.currency || 'CHF')
.toUpperCase(),
operator:
String(data.operator || ''),
terminal:
String(data.terminal || ''),
deviceId:
String(data.deviceId || ''),
details:
data.details &&
typeof data.details === 'object'
? data.details
: {},
createdAt:
data.createdAt
? new Date(data.createdAt)
: new Date()
};
try {
return await FiscalRecord.findOneAndUpdate(
{
tenantID,
recordId
},
{
$setOnInsert: record
},
{
upsert: true,
new: true
}
);
} catch (error) {
if (error?.code === 11000) {
return FiscalRecord.findOne({
tenantID,
recordId
});
}
console.error(
'[iCHEF FiscalRecord]',
error
);
return null;
}
}
