app.get('/api/public-receipt', async (req, res) => {
try {
const tenantID =
cleanString(
req.query?.tenantID
);
const token =
String(
req.query?.token ||
''
).trim();
if (
!tenantID ||
token.length < 16
) {
return res.status(400).send(
'Ticket invalide.'
);
}
const state =
await AppState.findOne({
tenantID
});
const history =
Array.isArray(
state?.activeOrders
?.FINANCIAL_HISTORY
?.data
)
? state.activeOrders
.FINANCIAL_HISTORY.data
: [];
const tx =
history.find(x =>
String(
x?.receipt
?.publicToken ||
''
) === token
);
if (!tx) {
return res.status(404).send(
'Ticket introuvable.'
);
}
const snapshot =
tx.orderSnapshot ||
{};
const items =
Array.isArray(
snapshot.items
)
? snapshot.items
: [];
const currency =
String(
tx.currency ||
'CHF'
);
const esc =
value =>
String(
value ??
''
)
.replace(
/&/g,
'&amp;'
)
.replace(
/</g,
'&lt;'
)
.replace(
/>/g,
'&gt;'
)
.replace(
/"/g,
'&quot;'
);
const lines =
items
.filter(i =>
!i?.cancelled
)
.map(i => {
const qty =
Number(
i?.qty ??
i?.quantity ??
1
);
const price =
Number(
i?.price ??
i?.p ??
0
);
return `
                        <tr>
                            <td>
                                ${esc(
i?.name ||
i?.n ||
'Article'
)}
                                ${qty > 1
? ` × ${qty}`
: ''}
                            </td>
                            <td style="text-align:right">
                                ${(price * qty)
.toFixed(2)}
                            </td>
                        </tr>
                    `;
})
.join('');
res.setHeader(
'Cache-Control',
'no-store'
);
res.setHeader(
'X-Robots-Tag',
'noindex,nofollow'
);
res.send(`
<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport"
content="width=device-width,initial-scale=1">
<title>Ticket ${esc(tx.ticketNumber)}</title>

<style>
body{
    margin:0;
    padding:20px;
    background:#f2f2f2;
    font-family:Arial,sans-serif;
    color:#111;
}
.ticket{
    max-width:420px;
    margin:auto;
    background:white;
    padding:24px;
    border-radius:12px;
}
h1{
    text-align:center;
    margin:0 0 5px;
}
.meta{
    text-align:center;
    color:#555;
    margin-bottom:20px;
}
table{
    width:100%;
    border-collapse:collapse;
}
td{
    padding:7px 0;
    border-bottom:1px solid #ddd;
}
.total{
    margin-top:18px;
    display:flex;
    justify-content:space-between;
    font-size:22px;
    font-weight:bold;
}
.proof{
    margin-top:20px;
    font-size:10px;
    color:#777;
    word-break:break-all;
}
@media print{
    body{
        background:white;
        padding:0;
    }
    .ticket{
        box-shadow:none;
    }
}
</style>
</head>

<body>

<div class="ticket">

<h1>iCHEF</h1>

<div class="meta">
Ticket ${esc(tx.ticketNumber || '—')}<br>
Table ${esc(tx.tableId || '—')}<br>
${esc(
new Date(
tx.createdAt ||
tx.date ||
Date.now()
).toLocaleString('fr-FR')
)}
</div>

<table>
${lines}
</table>

<div class="total">
<span>TOTAL</span>
<span>
${Number(
tx.total ??
tx.amount ??
0
).toFixed(2)}
${esc(currency)}
</span>
</div>

<div class="meta">
Paiement :
${esc(
tx.method ||
'—'
)}
</div>

<div class="proof">
Preuve :
${esc(
tx.ticketHash ||
tx.chainHash ||
'—'
)}
</div>

</div>

</body>
</html>
        `);
} catch (error) {
console.error(
'[iCHEF public receipt]',
error
);
res.status(500).send(
'Ticket indisponible.'
);
}
});
