// 👥 iCHEF STAFF PORTAL V108 — API SÉCURISÉE + DOCUMENTS RH
// ============================================================================

function ichefStaffPortalArray(node) {
    if (Array.isArray(node?.data)) {
        return node.data;
    }

    if (Array.isArray(node)) {
        return node;
    }

    return [];
}

function ichefRequireStaffSession(req) {
    const tenantID =
        cleanString(
            req.query?.tenantID ||
            req.body?.tenantID ||
            req.headers?.['x-ichef-tenant']
        );

    const claims =
        ichefVerifySignedSession(
            ichefBearerToken(req),
            {
                tenantID,
                scope: 'STAFF'
            }
        );

    if (
        !tenantID ||
        !claims?.staffId
    ) {
        return {
            ok: false,
            tenantID,
            claims: null,
            error:
                'Session staff invalide ou expirée.'
        };
    }

    const tokenDevice =
        String(
            claims.deviceId || ''
        ).trim();

    const requestDevice =
        String(
            req.headers?.['x-ichef-device'] ||
            ''
        ).trim();

    // Si le token a été créé pour un appareil précis,
    // il ne peut pas être rejoué depuis un autre appareil.
    if (
        tokenDevice &&
        (
            !requestDevice ||
            tokenDevice !== requestDevice
        )
    ) {
        return {
            ok: false,
            tenantID,
            claims: null,
            error:
                'Session staff non reconnue sur cet appareil.'
        };
    }

    if (
        ICHEF_STAFF_ACTIVATION_REQUIRED &&
        String(claims.accessChannel||'') === 'STAFF_PWA' &&
        claims.deviceTrusted !== true
    ) {
        return {
            ok:false,
            tenantID,
            claims:null,
            error:'Cet appareil doit être activé avec le QR iCHEF Staff fourni par votre responsable.'
        };
    }

    return {
        ok: true,
        tenantID,
        claims
    };
}

