app.post('/api/rh/documents/upload-binary', express.raw({type:'application/octet-stream',limit:'12mb'}), async (req,res) => {
    try {
        res.setHeader('Cache-Control','no-store');
        const auth=await ichefLoadRhDocumentsManagerSession(req);
        if(!auth.ok)return res.status(auth.status||401).json({success:false,error:auth.error});
        const staffId=String(req.query?.staffId||'').trim();
        const staffName=String(req.query?.staffName||'').trim().slice(0,140);
        const category=ichefRhDocumentCategorySafe(req.query?.category);
        const title=String(req.query?.title||req.query?.filename||'Document professionnel').trim().slice(0,160);
        const period=String(req.query?.period||'').trim().slice(0,100);
        const issuedRaw=String(req.query?.issuedAt||'').trim();
        const filename=String(req.query?.filename||'document').replace(/[^a-zA-Z0-9À-ÿ._ ()\-]/g,'_').slice(0,180);
        const mimeType=String(req.query?.mimeType||'application/octet-stream').toLowerCase().slice(0,120);
        if(!staffId||!filename)return res.status(400).json({success:false,error:'Document incomplet.'});
        if(!ichefRhDocumentMimeAllowed(mimeType,filename))return res.status(415).json({success:false,error:'Format non autorisé. Utilisez PDF, image, Word, Excel ou TXT.'});
        const state=await AppState.findOne({tenantID:auth.tenantID},{'activeOrders.STAFF_ACCESS':1,'activeOrders.DIRECTORY_MASTER':1}).lean();
        const directory=[...ichefStaffPortalArray(state?.activeOrders?.STAFF_ACCESS),...ichefStaffPortalArray(state?.activeOrders?.DIRECTORY_MASTER)];
        const staff=directory.find(s=>s?.active!==false&&String(s?.id??s?.staffId??s?.employeeId??'')===staffId);
        if(!staff)return res.status(404).json({success:false,code:'STAFF_NOT_SYNCED',error:'Collaborateur introuvable sur le serveur. Attendez la synchronisation RH puis réessayez.'});
        const buffer=Buffer.isBuffer(req.body)?req.body:Buffer.from(req.body||'');
        if(!buffer.length)return res.status(400).json({success:false,error:'Fichier vide ou illisible.'});
        if(buffer.length>12*1024*1024)return res.status(413).json({success:false,error:'Fichier trop volumineux (12 Mo maximum).'});
        if(mimeType==='application/pdf'&&buffer.slice(0,4).toString('ascii')!=='%PDF')return res.status(400).json({success:false,error:'PDF invalide.'});
        if(mimeType==='image/png'&&buffer.slice(1,4).toString('ascii')!=='PNG')return res.status(400).json({success:false,error:'Image PNG invalide.'});
        if(mimeType==='image/jpeg'&&!(buffer[0]===0xFF&&buffer[1]===0xD8))return res.status(400).json({success:false,error:'Image JPEG invalide.'});

        const securityScan=
            await ichefSecurityScanUploadBuffer(
                buffer,
                {
                    name:filename,
                    mime:mimeType,
                    context:'RH_DOCUMENT',
                    tenantID:auth.tenantID
                },
                req
            );

        if(!securityScan.ok){
            return res
                .status(
                    securityScan.status ||
                    422
                )
                .json({
                    success:false,
                    code:'SECURITY_FILE_BLOCKED',
                    error:
                        securityScan.error ||
                        'Document bloqué par la sécurité.'
                });
        }

        const uploadedAt=new Date();
        const issuedAt=issuedRaw&&Number.isFinite(Date.parse(issuedRaw))?new Date(issuedRaw):uploadedAt;
        const sha256=nodeCrypto.createHash('sha256').update(buffer).digest('hex');
        const upload=ichefRhStaffDocsBucket().openUploadStream(filename,{contentType:mimeType,metadata:{
            tenantID:auth.tenantID,staffId,staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),category,title,period,issuedAt,uploadedAt,
            uploadedBy:String(auth.claims?.actorName||'Direction / RH').slice(0,120),uploadedById:String(auth.claims?.actorId||'MASTER'),mimeType,sizeBytes:buffer.length,sha256,active:true
        }});
        await new Promise((resolve,reject)=>{upload.once('finish',resolve);upload.once('error',reject);upload.end(buffer);});
        // V114 : le flux GridFS a confirmé l'écriture. On répond immédiatement au navigateur
        // au lieu d'attendre une seconde lecture Mongo + l'audit, afin d'éviter les envois RH très longs.
        const storedLike={
            _id:upload.id,
            filename,
            length:buffer.length,
            uploadDate:uploadedAt,
            contentType:mimeType,
            metadata:{
                tenantID:auth.tenantID,staffId,
                staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),
                category,title,period,issuedAt,uploadedAt,
                uploadedBy:String(auth.claims?.actorName||'Direction / RH').slice(0,120),
                uploadedById:String(auth.claims?.actorId||'MASTER'),mimeType,sizeBytes:buffer.length,sha256,active:true
            }
        };
        const proof={
            proofId:`RH-DOC-${String(upload.id)}`,
            documentId:String(upload.id),
            tenantID:auth.tenantID,
            staffId,
            staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),
            category,title,fileName:filename,sizeBytes:buffer.length,sha256,
            sentAt:uploadedAt.toISOString(),storage:'MONGODB_GRIDFS',stored:true
        };
        const document={...ichefRhDocumentPublicMeta(req,storedLike,{signed:true}),proofId:proof.proofId};
        res.json({success:true,transport:'BINARY',document,proof});
        setImmediate(async()=>{
            try{
                await RhDocumentAudit.create({
                    tenantID:auth.tenantID,documentId:String(upload.id),staffId,
                    staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),
                    action:'UPLOAD',category,title,fileName:filename,sha256,
                    actorId:String(auth.claims?.actorId||'MASTER'),
                    actorName:String(auth.claims?.actorName||'Direction / RH').slice(0,120),
                    reason:`Document envoyé au collaborateur · preuve ${proof.proofId}`
                });
            }catch(error){console.warn('[iCHEF RH documents audit upload-binary]',error?.message||error);}
            try{ichefEmitStaffSyncRequired(auth.tenantID,{tableId:'RH_DOCUMENTS',source:'rh-document-upload-binary',staffId,timestamp:uploadedAt.toISOString()});}catch(_){}
            try{io.to(auth.tenantID).emit('staff-document-updated',{tenantID:auth.tenantID,staffId,type:'UPLOAD',proofId:proof.proofId,timestamp:uploadedAt.toISOString()});}catch(_){}
        });
        return;
    } catch(error) {
        console.error('[iCHEF RH documents upload-binary V113]',error);
        return res.status(error?.type==='entity.too.large'?413:500).json({success:false,error:error?.type==='entity.too.large'?'Fichier trop volumineux (12 Mo maximum).':(error?.message||'Envoi du document impossible.')});
    }
});

app.post('/api/rh/documents/upload', async (req,res) => {
    try {
        res.setHeader('Cache-Control','no-store');
        const auth=await ichefLoadRhDocumentsManagerSession(req);
        if(!auth.ok)return res.status(auth.status||401).json({success:false,error:auth.error});
        const staffId=String(req.body?.staffId||'').trim();
        const staffName=String(req.body?.staffName||'').trim().slice(0,140);
        const category=ichefRhDocumentCategorySafe(req.body?.category);
        const title=String(req.body?.title||req.body?.filename||'Document professionnel').trim().slice(0,160);
        const period=String(req.body?.period||'').trim().slice(0,100);
        const issuedRaw=String(req.body?.issuedAt||'').trim();
        const filename=String(req.body?.filename||'document').replace(/[^a-zA-Z0-9À-ÿ._ ()\-]/g,'_').slice(0,180);
        const mimeType=String(req.body?.mimeType||'application/octet-stream').toLowerCase().slice(0,120);
        const base64=String(req.body?.base64||'').replace(/^data:[^;]+;base64,/i,'').trim();
        if(!staffId||!filename||!base64)return res.status(400).json({success:false,error:'Document incomplet.'});
        if(!ichefRhDocumentMimeAllowed(mimeType,filename))return res.status(415).json({success:false,error:'Format non autorisé. Utilisez PDF, image, Word, Excel ou TXT.'});
        const state=await AppState.findOne({tenantID:auth.tenantID},{'activeOrders.STAFF_ACCESS':1,'activeOrders.DIRECTORY_MASTER':1}).lean();
        const directory=[...ichefStaffPortalArray(state?.activeOrders?.STAFF_ACCESS),...ichefStaffPortalArray(state?.activeOrders?.DIRECTORY_MASTER)];
        const staff=directory.find(s=>s?.active!==false&&String(s?.id??s?.staffId??s?.employeeId??'')===staffId);
        if(!staff)return res.status(404).json({success:false,error:'Collaborateur introuvable ou désactivé.'});
        let buffer; try{buffer=Buffer.from(base64,'base64');}catch(_){buffer=null;}
        if(!buffer?.length)return res.status(400).json({success:false,error:'Fichier vide ou illisible.'});
        if(buffer.length>12*1024*1024)return res.status(413).json({success:false,error:'Fichier trop volumineux (12 Mo maximum).'});
        if(mimeType==='application/pdf'&&buffer.slice(0,4).toString('ascii')!=='%PDF')return res.status(400).json({success:false,error:'PDF invalide.'});
        if(mimeType==='image/png'&&buffer.slice(1,4).toString('ascii')!=='PNG')return res.status(400).json({success:false,error:'Image PNG invalide.'});
        if(mimeType==='image/jpeg'&&!(buffer[0]===0xFF&&buffer[1]===0xD8))return res.status(400).json({success:false,error:'Image JPEG invalide.'});

        const securityScan=
            await ichefSecurityScanUploadBuffer(
                buffer,
                {
                    name:filename,
                    mime:mimeType,
                    context:'RH_DOCUMENT',
                    tenantID:auth.tenantID
                },
                req
            );

        if(!securityScan.ok){
            return res
                .status(
                    securityScan.status ||
                    422
                )
                .json({
                    success:false,
                    code:'SECURITY_FILE_BLOCKED',
                    error:
                        securityScan.error ||
                        'Document bloqué par la sécurité.'
                });
        }

        const uploadedAt=new Date();
        const issuedAt=issuedRaw&&Number.isFinite(Date.parse(issuedRaw))?new Date(issuedRaw):uploadedAt;
        const sha256=nodeCrypto.createHash('sha256').update(buffer).digest('hex');
        const upload=ichefRhStaffDocsBucket().openUploadStream(filename,{contentType:mimeType,metadata:{
            tenantID:auth.tenantID,staffId,staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),category,title,period,issuedAt,uploadedAt,
            uploadedBy:String(auth.claims?.actorName||'Direction / RH').slice(0,120),uploadedById:String(auth.claims?.actorId||'MASTER'),mimeType,sizeBytes:buffer.length,sha256,active:true
        }});
        await new Promise((resolve,reject)=>{upload.once('finish',resolve);upload.once('error',reject);upload.end(buffer);});
        const storedLike={
            _id:upload.id,filename,length:buffer.length,uploadDate:uploadedAt,contentType:mimeType,
            metadata:{tenantID:auth.tenantID,staffId,staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),category,title,period,issuedAt,uploadedAt,uploadedBy:String(auth.claims?.actorName||'Direction / RH').slice(0,120),uploadedById:String(auth.claims?.actorId||'MASTER'),mimeType,sizeBytes:buffer.length,sha256,active:true}
        };
        const proof={proofId:`RH-DOC-${String(upload.id)}`,documentId:String(upload.id),tenantID:auth.tenantID,staffId,staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),category,title,fileName:filename,sizeBytes:buffer.length,sha256,sentAt:uploadedAt.toISOString(),storage:'MONGODB_GRIDFS',stored:true};
        const document={...ichefRhDocumentPublicMeta(req,storedLike,{signed:true}),proofId:proof.proofId};
        res.json({success:true,transport:'JSON_FALLBACK',document,proof});
        setImmediate(async()=>{
            try{await RhDocumentAudit.create({tenantID:auth.tenantID,documentId:String(upload.id),staffId,staffName:String(staff.name||staffName||'Collaborateur').slice(0,140),action:'UPLOAD',category,title,fileName:filename,sha256,actorId:String(auth.claims?.actorId||'MASTER'),actorName:String(auth.claims?.actorName||'Direction / RH').slice(0,120),reason:`Document envoyé au collaborateur · preuve ${proof.proofId}`});}catch(error){console.warn('[iCHEF RH documents audit upload]',error?.message||error);}
            try{ichefEmitStaffSyncRequired(auth.tenantID,{tableId:'RH_DOCUMENTS',source:'rh-document-upload',staffId,timestamp:uploadedAt.toISOString()});}catch(_){}
            try{io.to(auth.tenantID).emit('staff-document-updated',{tenantID:auth.tenantID,staffId,type:'UPLOAD',proofId:proof.proofId,timestamp:uploadedAt.toISOString()});}catch(_){}
        });
        return;
    } catch(error) {
        console.error('[iCHEF RH documents upload V108]',error);
        return res.status(500).json({success:false,error:error?.message||'Envoi du document impossible.'});
    }
});

app.post('/api/rh/documents/delete', async (req,res) => {
    try {
        res.setHeader('Cache-Control','no-store');
        const auth=await ichefLoadRhDocumentsManagerSession(req);
        if(!auth.ok)return res.status(auth.status||401).json({success:false,error:auth.error});
        const objectId=ichefRhStaffDocObjectId(req.body?.documentId);
        const reason=String(req.body?.reason||'').trim();
        if(!objectId)return res.status(400).json({success:false,error:'Document invalide.'});
        if(reason.length<5)return res.status(400).json({success:false,error:'Motif de suppression obligatoire (5 caractères minimum).'});
        const files=await ichefRhStaffDocsBucket().find({_id:objectId,'metadata.tenantID':auth.tenantID}).limit(1).toArray();
        if(!files.length)return res.status(404).json({success:false,error:'Document introuvable.'});
        const file=files[0]; const staffId=String(file?.metadata?.staffId||'');
        console.warn('[iCHEF RH DOCUMENT DELETE]',{tenantID:auth.tenantID,documentId:String(objectId),staffId,actor:auth.claims?.actorName||'Direction / RH',reason});
        await RhDocumentAudit.create({
            tenantID:auth.tenantID,documentId:String(objectId),staffId,
            staffName:String(file?.metadata?.staffName||''),action:'DELETE',
            category:String(file?.metadata?.category||'OTHER'),
            title:String(file?.metadata?.title||file?.filename||''),
            fileName:String(file?.filename||''),sha256:String(file?.metadata?.sha256||''),
            actorId:String(auth.claims?.actorId||'MASTER'),
            actorName:String(auth.claims?.actorName||'Direction / RH').slice(0,120),reason
        }).catch(error=>console.warn('[iCHEF RH documents audit delete]',error?.message||error));
        await ichefRhStaffDocsBucket().delete(objectId);
        ichefEmitStaffSyncRequired(auth.tenantID,{tableId:'RH_DOCUMENTS',source:'rh-document-delete',staffId,timestamp:new Date().toISOString()});
        io.to(auth.tenantID).emit('staff-document-updated',{tenantID:auth.tenantID,staffId,type:'DELETE',timestamp:new Date().toISOString()});
        return res.json({success:true});
    } catch(error) {
        console.error('[iCHEF RH documents delete V108]',error);
        return res.status(500).json({success:false,error:'Suppression du document impossible.'});
    }
});

app.get('/api/rh/documents/file/:id', async (req,res) => {
    try {
        const objectId=ichefRhStaffDocObjectId(req.params.id);
        const token=String(req.query?.token||'').trim();
        if(!objectId||!token)return res.status(400).send('Lien document invalide.');
        const claims=ichefVerifySignedSession(token,{scope:'RH_STAFF_DOCUMENT_FILE'});
        if(!claims||String(claims.documentId||'')!==String(objectId))return res.status(403).send('Lien expiré ou non autorisé.');
        const tenantID=cleanString(claims.tenantID||''); const staffId=String(claims.staffId||'');
        const tenant=await Tenant.findOne({tenantID},{tenantID:1,status:1,archivedAt:1}).lean();
        if(!tenant||tenant.archivedAt||String(tenant.status||'').toUpperCase()!=='ACTIF')return res.status(403).send('Accès établissement suspendu.');
        const state=await AppState.findOne({tenantID},{'activeOrders.STAFF_ACCESS':1,'activeOrders.DIRECTORY_MASTER':1}).lean();
        const staffPool=[...ichefStaffPortalArray(state?.activeOrders?.STAFF_ACCESS),...ichefStaffPortalArray(state?.activeOrders?.DIRECTORY_MASTER)];
        const activeStaff=staffPool.some(item=>item?.active!==false&&String(item?.id??item?.staffId??item?.employeeId??'')===staffId);
        if(!activeStaff)return res.status(403).send('Accès collaborateur désactivé.');
        const files=await ichefRhStaffDocsBucket().find({_id:objectId,'metadata.tenantID':tenantID,'metadata.staffId':staffId,'metadata.active':{$ne:false}}).limit(1).toArray();
        if(!files.length)return res.status(404).send('Document introuvable.');
        const file=files[0]; const mime=String(file?.metadata?.mimeType||file?.contentType||'application/octet-stream');
        const safeFilename=String(file?.filename||'document').replace(/["\r\n]/g,'_');
        const inline=/^(application\/pdf|image\/png|image\/jpeg)$/i.test(mime);
        res.set('Cache-Control','private, no-store, max-age=0');
        res.set('Referrer-Policy','no-referrer');
        res.set('X-Content-Type-Options','nosniff');
        res.set('Content-Type',mime);
        res.set('Content-Disposition',`${inline?'inline':'attachment'}; filename="${safeFilename}"`);
        ichefRhStaffDocsBucket().openDownloadStream(objectId).on('error',()=>{if(!res.headersSent)res.status(404).end();else res.end();}).pipe(res);
    } catch(error) {
        console.error('[iCHEF RH documents file V108]',error);
        if(!res.headersSent)return res.status(500).send('Document indisponible.');
        res.end();
    }
});


// Coffre-fort RH personnel : lecture seule, session Staff obligatoire.
app.get(
    '/api/staff/documents',
    async (req,res) => {
        try {
            res.setHeader('Cache-Control','no-store');
            const auth = await ichefLoadActiveStaffSession(req);
            if (!auth.ok) {
                return res.status(401).json({success:false,error:auth.error});
            }

            const {staff,state} = auth;
            const activeOrders = state?.activeOrders || {};
            const rhStaff = ichefStaffRhFindDirectoryMember(activeOrders,staff);
            const legacyDocuments = ichefStaffRhDocumentsForStaff(activeOrders,staff,rhStaff);
            const secureDocuments = await ichefRhListStaffDocuments(
                req,
                auth.tenantID,
                ichefStaffRhCandidateIds(staff,rhStaff)
            );
            const secureKeys = new Set(secureDocuments.map(item => String(item?.documentId || item?.id || '')));
            const documents = [
                ...secureDocuments,
                ...legacyDocuments.filter(item => !secureKeys.has(String(item?.documentId || item?.id || '')))
            ];

            const counts = documents.reduce((acc,document) => {
                const key = String(document.category || 'OTHER').toUpperCase();
                acc.total += 1;
                acc[key] = (acc[key] || 0) + 1;
                return acc;
            },{
                total:0,
                PAYSLIP:0,
                CONTRACT:0,
                ATTESTATION:0,
                CERTIFICATE:0,
                OTHER:0
            });

            return res.json({
                success:true,
                private:true,
                readOnly:true,
                documents,
                counts,
                serverTime:new Date().toISOString()
            });
        } catch(error) {
            console.error('[iCHEF STAFF documents V105]',error);
            return res.status(500).json({
                success:false,
                error:'Documents RH momentanément indisponibles.'
            });
        }
    }
);



// ============================================================================
// 📊 iCHEF ADMIN COLLABORATEURS V166 — JOUR / SEMAINE / MOIS / 2 MOIS
// ============================================================================
app.get('/api/staff/admin/overview',async(req,res)=>{
    try{
        res.setHeader('Cache-Control','no-store');

        const auth =
            await ichefLoadStaffActivationManagerSession(req);

        if(!auth.ok){
            return res
                .status(auth.status||401)
                .json({
                    success:false,
                    error:auth.error
                });
        }

        const [
            state,
            memoRows
        ] = await Promise.all([
            AppState.findOne({
                tenantID:auth.tenantID
            }).lean(),
            StaffAdminMemo.find({
                tenantID:auth.tenantID
            }).lean()
        ]);

        const memoMap =
            new Map(
                (memoRows||[])
                    .map(row=>[
                        String(row.staffId||''),
                        row
                    ])
            );

        const activeOrders =
            state?.activeOrders || {};

        const access =
            ichefStaffPortalArray(
                activeOrders.STAFF_ACCESS
            )
            .filter(x=>x && x.active!==false);

        const punches =
            ichefStaffPortalArray(
                activeOrders.PUNCHES_MASTER
            );

        const now = new Date();
        const todayIso = ichefStaffRhIsoDate(now);
        const todayStart =
            new Date(
                now.getFullYear(),
                now.getMonth(),
                now.getDate()
            ).getTime();

        const weekDay =
            now.getDay() || 7;

        const weekStart =
            todayStart -
            (weekDay-1)*86400000;

        const rows=[];

        for(const staff of access){
            const rhStaff =
                ichefStaffRhFindDirectoryMember(
                    activeOrders,
                    staff
                );

            const staffId =
                String(
                    staff.id ||
                    staff.staffId ||
                    rhStaff?.id ||
                    ''
                );

            const email =
                ichefStaffProfileEmail({
                    member:staff,
                    directoryEntry:rhStaff||{}
                });

            const memoDoc =
                memoMap.get(staffId) || null;

            const currentMonth =
                ichefStaffRhMonthMetrics({
                    activeOrders,
                    punches,
                    staff,
                    rhStaff,
                    monthDate:new Date(
                        now.getFullYear(),
                        now.getMonth(),
                        1,12,0,0,0
                    )
                });

            const nextMonth =
                ichefStaffRhMonthMetrics({
                    activeOrders,
                    punches,
                    staff,
                    rhStaff,
                    monthDate:new Date(
                        now.getFullYear(),
                        now.getMonth()+1,
                        1,12,0,0,0
                    )
                });

            const schedule =
                ichefStaffRhBuildSchedule(
                    activeOrders,
                    staff,
                    rhStaff,
                    70
                );

            const today =
                schedule.find(
                    row=>row.date===todayIso
                ) || null;

            const weekSchedule =
                schedule.filter(row=>{
                    const ts =
                        Date.parse(
                            `${row.date}T12:00:00`
                        );

                    return (
                        Number.isFinite(ts) &&
                        ts>=weekStart &&
                        ts<weekStart+7*86400000
                    );
                });

            const weekPlanned =
                Math.round(
                    weekSchedule.reduce(
                        (sum,row)=>
                            sum+
                            Number(
                                row.counterPlannedHours ??
                                row.plannedHours ??
                                0
                            ),
                        0
                    )*100
                )/100;

            const weekWorked =
                ichefStaffRhWorkedWindow({
                    activeOrders,
                    punches,
                    staff,
                    rhStaff,
                    fromMs:weekStart,
                    toMs:Date.now()
                }).rh;

            const ids =
                new Set(
                    ichefStaffRhCandidateIds(
                        staff,
                        rhStaff
                    ).map(String)
                );

            let lateMinutesMonth=0;
            let lateCountMonth=0;
            let sicknessDaysMonth=0;

            const monthKey =
                ichefStaffRhMonthKey(now);

            for(
                const day of schedule.filter(
                    row=>
                        String(row.date||'')
                            .startsWith(monthKey)
                )
            ){
                const status =
                    String(day.status||'')
                        .toLowerCase();

                if(status==='maladie'){
                    sicknessDaysMonth++;
                }

                if(
                    !day.start ||
                    ![
                        'present',
                        'off_matin',
                        'off_soir',
                        'ferie'
                    ].includes(status)
                ){
                    continue;
                }

                const dateMs =
                    Date.parse(
                        `${day.date}T00:00:00`
                    );

                if(
                    !Number.isFinite(dateMs) ||
                    dateMs>Date.now()
                ){
                    continue;
                }

                const firstPunch =
                    (Array.isArray(punches)?punches:[])
                        .filter(p=>
                            ids.has(
                                String(p?.staffId||'')
                            )
                        )
                        .filter(p=>{
                            const ts =
                                Number(p?.timestamp||0);

                            return (
                                ts>=dateMs &&
                                ts<dateMs+86400000
                            );
                        })
                        .filter(p=>
                            /ENTR|IN|ARRIV/i.test(
                                String(p?.type||'')
                            )
                        )
                        .sort(
                            (a,b)=>
                                Number(a.timestamp||0)-
                                Number(b.timestamp||0)
                        )[0];

                if(!firstPunch){
                    continue;
                }

                const [hh,mm] =
                    String(day.start)
                        .split(':')
                        .map(Number);

                const plannedStart =
                    dateMs+
                    (Number(hh)||0)*3600000+
                    (Number(mm)||0)*60000;

                const delay =
                    Math.max(
                        0,
                        Math.floor(
                            (
                                Number(firstPunch.timestamp)-
                                plannedStart
                            )/60000
                        )
                    );

                if(delay>0){
                    lateMinutesMonth+=delay;
                    lateCountMonth++;
                }
            }

            rows.push({
                id:staffId,
                name:String(
                    staff.name ||
                    rhStaff?.name ||
                    'Collaborateur'
                ),
                role:String(
                    staff.role ||
                    rhStaff?.role ||
                    ''
                ),
                dept:String(
                    staff.dept ||
                    rhStaff?.dept ||
                    ''
                ),

                // Jamais de PIN retourné à l'Admin.
                pinConfigured:Boolean(
                    String(
                        staff.pin ??
                        rhStaff?.pin ??
                        ''
                    ).trim()
                ),

                emailConfigured:Boolean(email),
                maskedEmail:
                    email
                        ? ichefStaffMaskEmail(email)
                        : '',

                memo:String(
                    memoDoc?.memo || ''
                ).slice(0,1200),

                memoUpdatedAt:
                    memoDoc?.updatedAt || null,

                memoUpdatedBy:
                    String(
                        memoDoc?.updatedByName ||
                        ''
                    ),

                onDuty:
                    staff.onDuty===true,

                today,

                week:{
                    plannedHours:weekPlanned,
                    workedHours:
                        Math.round(
                            Number(weekWorked||0)*100
                        )/100,
                    balance:
                        Math.round(
                            (
                                Number(weekWorked||0)-
                                Number(weekPlanned||0)
                            )*100
                        )/100
                },

                month:{
                    ...currentMonth,
                    lateMinutes:lateMinutesMonth,
                    lateCount:lateCountMonth,
                    sicknessDays:sicknessDaysMonth
                },

                nextMonth,

                schedule:
                    schedule.slice(0,70)
            });
        }

        const totals =
            rows.reduce(
                (acc,row)=>{
                    acc.staff++;

                    if(row.onDuty){
                        acc.onDuty++;
                    }

                    acc.overtime +=
                        Number(
                            row.month?.overtime||0
                        );

                    acc.negative +=
                        Number(
                            row.month?.recoveryDue||0
                        );

                    acc.lateMinutes +=
                        Number(
                            row.month?.lateMinutes||0
                        );

                    acc.sicknessDays +=
                        Number(
                            row.month?.sicknessDays||0
                        );

                    return acc;
                },
                {
                    staff:0,
                    onDuty:0,
                    overtime:0,
                    negative:0,
                    lateMinutes:0,
                    sicknessDays:0
                }
            );

        totals.overtime =
            Math.round(
                totals.overtime*100
            )/100;

        totals.negative =
            Math.round(
                totals.negative*100
            )/100;

        return res.json({
            success:true,
            tenantID:auth.tenantID,
            serverTime:
                new Date()
                    .toISOString(),
            totals,
            rows
        });

    }catch(error){
        console.error(
            '[iCHEF ADMIN STAFF OVERVIEW V167]',
            error
        );

        return res
            .status(500)
            .json({
                success:false,
                error:
                    'Synthèse collaborateurs momentanément indisponible.'
            });
    }
});

