function ichefRhPlanningSettings(activeOrders = {}) {
    const raw = activeOrders?.RH_SETTINGS?.data;
    return raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
}

function ichefRhIsoDateList(startDate, endDate, maxDays = 62) {
    const out = [];
    const start = new Date(`${String(startDate || '')}T12:00:00`);
    const end = new Date(`${String(endDate || '')}T12:00:00`);
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end < start) return out;
    let cursor = new Date(start);
    while (cursor <= end && out.length < maxDays) {
        out.push(`${cursor.getFullYear()}-${String(cursor.getMonth()+1).padStart(2,'0')}-${String(cursor.getDate()).padStart(2,'0')}`);
        cursor.setDate(cursor.getDate()+1);
    }
    return out;
}

function ichefRhReservationDate(row = {}) {
    const raw = row.date || row.reservationDate || row.bookingDate || row.startDate || row.start || row.datetime || row.dateTime || row.when || '';
    const text = String(raw || '').trim();
    const match = text.match(/^(\d{4}-\d{2}-\d{2})/);
    if (match) return match[1];
    const parsed = Date.parse(text);
    if (!Number.isFinite(parsed)) return '';
    const d = new Date(parsed);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

function ichefRhReservationCovers(row = {}) {
    const n = Number(row.covers ?? row.guests ?? row.pax ?? row.persons ?? row.people ?? row.partySize ?? row.nbPersons ?? row.count ?? 0);
    return Number.isFinite(n) && n > 0 ? n : 0;
}

function ichefRhAiPeakDates(activeOrders = {}, settings = {}) {
    if (settings?.planningProtectPeakLeave === false) return new Set();
    const peaks = new Set();
    const ai = activeOrders?.RH_AI_DEMAND?.data;
    const rows = [
        ...(Array.isArray(ai?.highDemandDays) ? ai.highDemandDays : []),
        ...(Array.isArray(ai?.protectedPeakDays) ? ai.protectedPeakDays : [])
    ];
    for (const row of rows) {
        const raw = typeof row === 'string' ? row : (row?.date || row?.day || '');
        const match = String(raw || '').match(/\d{4}-\d{2}-\d{2}/);
        if (match) peaks.add(match[0]);
    }

    const reservations = Array.isArray(activeOrders?.RESERVATIONS_MASTER?.data)
        ? activeOrders.RESERVATIONS_MASTER.data
        : [];
    const byMonth = new Map();
    for (const row of reservations) {
        const date = ichefRhReservationDate(row);
        if (!date) continue;
        const month = date.slice(0,7);
        if (!byMonth.has(month)) byMonth.set(month, new Map());
        const m = byMonth.get(month);
        m.set(date, (m.get(date) || 0) + ichefRhReservationCovers(row));
    }
    const limit = Math.max(1, Math.min(31, Number(settings?.planningPeakProtectionCount) || 6));
    const minCovers = Math.max(0, Number(settings?.planningPeakMinCovers) || 40);
    for (const monthMap of byMonth.values()) {
        [...monthMap.entries()]
            .filter(([,covers]) => Number(covers) >= minCovers)
            .sort((a,b) => b[1]-a[1])
            .slice(0,limit)
            .forEach(([date]) => peaks.add(date));
    }
    return peaks;
}

function ichefRhProtectedRequestDates(activeOrders = {}, settings = {}, startDate = '', endDate = '') {
    const dates = ichefRhIsoDateList(startDate, endDate, 62);
    const protectedWeekdays = new Set(
        (Array.isArray(settings?.planningProtectedWeekdays) ? settings.planningProtectedWeekdays : [])
            .map(Number).filter(v => Number.isInteger(v) && v >= 0 && v <= 6)
    );
    const peakDates = ichefRhAiPeakDates(activeOrders, settings);
    const rows = [];
    for (const date of dates) {
        const d = new Date(`${date}T12:00:00`);
        if (settings?.planningBlockPlannableLeaveOnProtectedDays !== false && protectedWeekdays.has(d.getDay())) {
            rows.push({date, reason:'JOUR_PROTEGE'});
            continue;
        }
        if (settings?.planningProtectPeakLeave !== false && peakDates.has(date)) {
            rows.push({date, reason:'PIC_AFFLUENCE'});
        }
    }
    return rows;
}

app.post(
    '/api/staff/requests',
    async (req,res) => {
        try {
            const auth =
                await ichefLoadActiveStaffSession(
                    req
                );

            if (!auth.ok) {
                return res
                    .status(401)
                    .json({
                        success:false,
                        error:auth.error
                    });
            }

            const canonicalType =
                ichefStaffRhCanonicalRequestType(
                    req.body?.type
                );

            const startDate =
                String(
                    req.body?.startDate ||
                    ''
                )
                .trim();

            const endDate =
                String(
                    req.body?.endDate ||
                    startDate
                )
                .trim();

            const note =
                String(
                    req.body?.note ||
                    ''
                )
                .trim()
                .slice(0,500);

            if (
                ![
                    'JOUR_OFF',
                    'VACANCES',
                    'RECUPERATION'
                ].includes(canonicalType) ||
                !/^\d{4}-\d{2}-\d{2}$/.test(startDate) ||
                !/^\d{4}-\d{2}-\d{2}$/.test(endDate) ||
                endDate < startDate
            ) {
                return res
                    .status(400)
                    .json({
                        success:false,
                        error:
                            'Demande staff invalide.'
                    });
            }

            const {
                state,
                staff,
                tenantID
            } = auth;

            if (!state.activeOrders) {
                state.activeOrders = {};
            }

            // V112 — jours protégés et pics d'affluence : uniquement pour les nouvelles
            // demandes planifiables (OFF, vacances, récupération). Les absences obligatoires
            // comme maladie/accident sont gérées par RH et ne passent pas par cette porte.
            const rhPlanningSettings = ichefRhPlanningSettings(state.activeOrders);
            const blockedRequestDates = ichefRhProtectedRequestDates(
                state.activeOrders,
                rhPlanningSettings,
                startDate,
                endDate
            );
            if (blockedRequestDates.length) {
                const peak = blockedRequestDates.some(row => row.reason === 'PIC_AFFLUENCE');
                return res.status(409).json({
                    success:false,
                    code:peak ? 'RH_PEAK_PERIOD_PROTECTED' : 'RH_PROTECTED_DAY',
                    error:peak
                        ? 'Cette période est protégée en raison d’un pic d’affluence prévu. Contactez votre responsable RH si la demande est indispensable.'
                        : 'Cette période fait partie des jours protégés de l’établissement. Contactez votre responsable RH si la demande est indispensable.',
                    blockedDates:blockedRequestDates.slice(0,31)
                });
            }

            const rhStaff =
                ichefStaffRhFindDirectoryMember(
                    state.activeOrders,
                    staff
                );

            const now =
                new Date()
                    .toISOString();

            const random =
                nodeCrypto
                    .randomBytes(3)
                    .toString('hex')
                    .toUpperCase();

            const requestNumber =
                `REQ-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}-${random}`;

            const request = {
                id:requestNumber,
                requestNumber,
                proofId:requestNumber,
                tenantID,
                staffId:
                    rhStaff?.id ||
                    staff.id,
                technicalStaffId:
                    staff.id,
                staffPin:
                    String(
                        staff.pin ||
                        rhStaff?.pin ||
                        ''
                    ),
                staffName:
                    staff.name ||
                    rhStaff?.name ||
                    'Collaborateur',
                role:
                    staff.role ||
                    rhStaff?.role ||
                    '',
                dept:
                    staff.dept ||
                    rhStaff?.dept ||
                    '',
                type:
                    ichefStaffRhLegacyRequestType(
                        canonicalType
                    ),
                requestType:
                    canonicalType,
                startDate,
                endDate,
                start:startDate,
                end:endDate,
                note,
                comment:note,
                status:'pending',
                createdAt:now,
                updatedAt:now,
                source:'STAFF_PORTAL',
                history:[
                    {
                        action:'CREATED',
                        at:now,
                        by:
                            staff.name ||
                            rhStaff?.name ||
                            'Collaborateur',
                        status:'PENDING'
                    }
                ]
            };

            const staffRequests =
                ichefStaffPortalArray(
                    state.activeOrders.STAFF_REQUESTS
                )
                .slice(-999);

            const rhRequests =
                ichefStaffPortalArray(
                    state.activeOrders.REQUESTS_MASTER
                )
                .slice(-999);

            staffRequests.push({...request});
            rhRequests.push({...request});

            state.activeOrders.STAFF_REQUESTS = {
                data:staffRequests,
                updatedAt:now
            };

            state.activeOrders.REQUESTS_MASTER = {
                data:rhRequests,
                updatedAt:now
            };

            state.markModified(
                'activeOrders'
            );

            await state.save();

            io.to(tenantID).emit(
                'staff-request-created',
                {
                    tenantID,
                    request,
                    timestamp:now
                }
            );

            ichefEmitFullState(
                tenantID,
                state,
                {
                    tableId:'STAFF_REQUESTS',
                    source:'staff-portal-v67'
                }
            );

            return res.json({
                success:true,
                request:
                    ichefStaffRhNormalizeRequest(
                        request
                    ),
                proof:{
                    id:requestNumber,
                    createdAt:now,
                    staffName:request.staffName,
                    type:canonicalType,
                    startDate,
                    endDate,
                    status:'PENDING'
                }
            });

        } catch(error) {
            console.error(
                '[iCHEF STAFF request V112]',
                error
            );

            return res
                .status(500)
                .json({
                    success:false,
                    error:
                        'La demande n’a pas pu être enregistrée.'
                });
        }
    }
);

async function ichefStaffPortalClock(
    req,
    res,
    desiredType
) {
    try {
        const auth =
            await ichefLoadActiveStaffSession(
                req
            );

        if (!auth.ok) {
            return res
                .status(401)
                .json({
                    success:false,
                    error:
                        auth.error
                });
        }

        const {
            state,
            staff,
            staffAccess,
            tenantID
        } = auth;

        const desiredOnDuty =
            desiredType ===
            'ENTRÉE';

        if (
            Boolean(
                staff.onDuty
            ) ===
            desiredOnDuty
        ) {
            return res.json({
                success:true,
                unchanged:true,
                onDuty:
                    desiredOnDuty
            });
        }

        const now =
            Date.now();

        const punch =
            {
                id:
                    'staffportal_' +
                    tenantID +
                    '_' +
                    now +
                    '_' +
                    nodeCrypto
                        .randomBytes(4)
                        .toString('hex'),
                tenantID,
                staffId:
                    staff.id,
                staffName:
                    staff.name ||
                    '',
                dept:
                    staff.dept ||
                    '',
                role:
                    staff.role ||
                    '',
                type:
                    desiredType,
                timestamp:
                    now,
                serverRecordedAt:
                    new Date(now)
                        .toISOString(),
                clientRecordedAt:
                    null,
                offlineSync:
                    false,
                timestampSource:
                    'SERVER',
                deviceId:
                    String(
                        req.headers
                            ?.['x-ichef-device'] ||
                        ''
                    )
                    .trim()
                    .slice(
                        0,
                        200
                    ),
                terminal:
                    'STAFF_PORTAL',
                photo:''
            };

        const punches =
            ichefStaffPortalArray(
                state.activeOrders
                    ?.PUNCHES_MASTER
            )
            .slice();

        punches.push(
            punch
        );

        const safePunches =
            punches
                .slice(-2500)
                .map(
                    (item,index,array) => {
                        const keepPhoto =
                            index >=
                            array.length -
                            12;

                        if (
                            keepPhoto ||
                            !item?.photo
                        ) {
                            return item;
                        }

                        return {
                            ...item,
                            photo:'',
                            photoArchived:true
                        };
                    }
                );

        if (!state.activeOrders) {
            state.activeOrders = {};
        }

        state.activeOrders
            .PUNCHES_MASTER = {
                data:
                    safePunches,
                updatedAt:
                    new Date(now)
                        .toISOString()
            };

        const previousTimesheets =
            state.activeOrders
                ?.RH_TIMESHEET_REAL
                ?.data || {
                    months:{}
                };

        state.activeOrders
            .RH_TIMESHEET_REAL = {
                data:
                    ichefRhBuildWorkedTimesheets(
                        safePunches,
                        previousTimesheets
                    ),
                updatedAt:
                    new Date(now)
                        .toISOString()
            };

        const staffIndex =
            staffAccess
                .findIndex(item =>
                    String(
                        item?.id ||
                        ''
                    ) ===
                    String(
                        staff.id
                    )
                );

        if (staffIndex < 0) {
            staffAccess.push({
                ...staff,
                id:String(staff.id),
                active:staff.active !== false,
                onDuty:desiredOnDuty,
                lastPunchAt:new Date(now).toISOString(),
                lastPunchType:desiredType
            });

            state.activeOrders.STAFF_ACCESS = {
                data:staffAccess,
                updatedAt:new Date(now).toISOString()
            };
        } else {
            staffAccess[
                staffIndex
            ] = {
                ...staffAccess[
                    staffIndex
                ],
                onDuty:
                    desiredOnDuty,
                lastPunchAt:
                    new Date(now)
                        .toISOString(),
                lastPunchType:
                    desiredType
            };

            state.activeOrders
                .STAFF_ACCESS = {
                    data:
                        staffAccess,
                    updatedAt:
                        new Date(now)
                            .toISOString()
                };
        }

        state.markModified(
            'activeOrders'
        );

        await state.save();

        try {
            const archiveDetails =
                {
                    ...punch
                };

            delete archiveDetails.photo;

            await RhPunchRecord
                .updateOne(
                    {
                        tenantID,
                        punchId:
                            punch.id
                    },
                    {
                        $setOnInsert:{
                            tenantID,
                            punchId:
                                punch.id,
                            staffId:
                                String(
                                    punch.staffId
                                ),
                            timestamp:
                                Number(
                                    punch.timestamp
                                ),
                            type:
                                punch.type,
                            photo:'',
                            details:
                                archiveDetails,
                            createdAt:
                                new Date(now)
                        }
                    },
                    {
                        upsert:true
                    }
                );

        } catch(archiveError) {
            console.warn(
                '[iCHEF STAFF] archive pointage non bloquante :',
                archiveError?.message ||
                archiveError
            );
        }

        io.to(
            tenantID
        ).emit(
            'staffDutyChanged',
            {
                staffId:
                    staff.id,
                staffName:
                    staff.name ||
                    '',
                dept:
                    staff.dept ||
                    '',
                onDuty:
                    desiredOnDuty,
                punchType:
                    desiredType,
                timestamp:
                    now
            }
        );

        ichefEmitFullState(
            tenantID,
            state,
            {
                tableId:
                    'PUNCHES_MASTER',
                source:
                    'staff-portal'
            }
        );

        return res.json({
            success:true,
            onDuty:
                desiredOnDuty,
            punchType:
                desiredType,
            punch
        });

    } catch(error) {
        console.error(
            '[iCHEF STAFF clock]',
            error
        );

        return res
            .status(500)
            .json({
                success:false,
                error:
                    'Pointage staff impossible.'
            });
    }
}

