function ichefFrozenBuildVatSummary(
orderSnapshot = {},
fallbackTotal = 0
) {
const items =
Array.isArray(orderSnapshot?.items)
? orderSnapshot.items
: [];
const groups = new Map();
let calculatedHT = 0;
let calculatedVAT = 0;
let calculatedTTC = 0;
let hasRate = false;
const round2 =
value =>
Math.round(
Number(value || 0) * 100
) / 100;
for (const item of items) {
if (item?.cancelled === true) continue;
const qty =
Math.max(
0,
Number(
item?.qty ??
item?.quantity ??
1
) || 0
);
const unitTTC =
Number(
item?.price ??
item?.p ??
item?.unitPrice ??
0
) || 0;
const lineTTC =
round2(unitTTC * qty);
const rawRate =
item?.vatRate ??
item?.tva ??
item?.taxRate ??
null;
const rate =
rawRate === null ||
rawRate === undefined ||
rawRate === ''
? null
: Number(rawRate);
calculatedTTC +=
lineTTC;
if (
Number.isFinite(rate) &&
rate >= 0 &&
rate <= 100
) {
hasRate = true;
const lineHT =
rate === 0
? lineTTC
: lineTTC /
(1 + rate / 100);
const lineVAT =
lineTTC -
lineHT;
calculatedHT +=
lineHT;
calculatedVAT +=
lineVAT;
const key =
Number(rate)
.toFixed(3);
const current =
groups.get(key) || {
rate:
Number(rate),
baseHT:
0,
vat:
0,
totalTTC:
0
};
current.baseHT +=
lineHT;
current.vat +=
lineVAT;
current.totalTTC +=
lineTTC;
groups.set(
key,
current
);
}
}
const totalTTC =
round2(
Number(
orderSnapshot?.totalTTC ??
orderSnapshot?.total ??
fallbackTotal ??
calculatedTTC
) || 0
);
const totalHT =
hasRate
? round2(calculatedHT)
: round2(
Number(
orderSnapshot?.totalHT ??
0
) || 0
);
const totalVAT =
hasRate
? round2(calculatedVAT)
: round2(
Number(
orderSnapshot?.totalTVA ??
orderSnapshot?.vatTotal ??
0
) || 0
);
return {
calculated:
hasRate,
totalTTC,
totalHT,
totalVAT,
rates:
Array.from(
groups.values()
)
.map(group => ({
rate:
Number(group.rate),
baseHT:
round2(group.baseHT),
vat:
round2(group.vat),
totalTTC:
round2(group.totalTTC)
}))
.sort(
(a, b) =>
Number(a.rate) -
Number(b.rate)
)
};
}
function ichefFrozenFiscalHashBase(transaction = {}) {
const clone =
JSON.parse(
JSON.stringify(
transaction || {}
)
);
delete clone.ticketHash;
delete clone.fiscalControlUrl;
delete clone.serverControlVerifiedAt;
if (
clone.receipt &&
typeof clone.receipt === 'object'
) {
delete clone.receipt.publicUrl;
}
return clone;
}
function ichefFrozenVerifyTicketHash(transaction = {}) {
const stored =
String(
transaction?.ticketHash ||
''
);
if (!stored) {
return {
available: false,
valid: false,
stored: '',
recomputed: ''
};
}
const recomputed =
nodeCrypto
.createHash('sha256')
.update(
JSON.stringify(
ichefFrozenFiscalHashBase(
transaction
)
)
)
.digest('hex');
return {
available: true,
valid:
stored === recomputed,
stored,
recomputed
};
}
async function ichefFrozenVerifyAuditChainForTicket(
tenantID,
ticketNumber
) {
const safeID =
cleanString(tenantID);
const logs =
await AuditLog
.find({
tenantID:
safeID
})
.sort({
timestamp: 1,
_id: 1
})
.lean();
let chainValid = true;
let brokenAt = null;
for (
let index = 0;
index < logs.length;
index += 1
) {
const log =
logs[index];
const expectedPrevious =
index === 0
? 'GENESIS_BLOCK_0000000000000000'
: String(
logs[index - 1]
?.currentHash ||
''
);
if (
String(
log?.previousHash ||
''
) !==
expectedPrevious
) {
chainValid = false;
brokenAt = index;
break;
}
const dataString =
JSON.stringify({
tenantID:
safeID,
action:
log.action,
entityType:
log.entityType,
entityId:
log.entityId,
authorPin:
log.authorPin,
details:
log.details,
previousHash:
log.previousHash
});
const recomputed =
nodeCrypto
.createHash('sha256')
.update(dataString)
.digest('hex');
if (
String(
log?.currentHash ||
''
) !==
recomputed
) {
chainValid = false;
brokenAt = index;
break;
}
}
const targetIndex =
logs.findIndex(log =>
String(
log?.entityId ||
''
) ===
String(
ticketNumber ||
''
) &&
String(
log?.action ||
''
).toUpperCase() ===
'CASH_IN'
);
const target =
targetIndex >= 0
? logs[targetIndex]
: null;
return {
recordFound:
Boolean(target),
chainValid,
brokenAt,
position:
targetIndex >= 0
? targetIndex + 1
: null,
totalRecords:
logs.length,
timestamp:
target?.timestamp ||
null,
previousHash:
target?.previousHash ||
null,
currentHash:
target?.currentHash ||
null,
action:
target?.action ||
null,
entityType:
target?.entityType ||
null
};
}
function ichefFiscalPeriodRange(
period,
key
) {
const kind =
String(period || '')
.trim()
.toLowerCase();
const rawKey =
String(key || '')
.trim();
let start = null;
let end = null;
if (
kind === 'day' &&
/^\d{4}-\d{2}-\d{2}$/.test(rawKey)
) {
start =
new Date(
`${rawKey}T00:00:00.000Z`
);
end =
new Date(
start.getTime() +
24 * 60 * 60 * 1000
);
}
if (
kind === 'month' &&
/^\d{4}-\d{2}$/.test(rawKey)
) {
const [year, month] =
rawKey
.split('-')
.map(Number);
start =
new Date(
Date.UTC(
year,
month - 1,
1
)
);
end =
new Date(
Date.UTC(
year,
month,
1
)
);
}
if (
kind === 'year' &&
/^\d{4}$/.test(rawKey)
) {
const year =
Number(rawKey);
start =
new Date(
Date.UTC(
year,
0,
1
)
);
end =
new Date(
Date.UTC(
year + 1,
0,
1
)
);
}
return {
start,
end
};
}
