function ichefOpsId(prefix='OPS'){return `${prefix}_${Date.now()}_${nodeCrypto.randomBytes(8).toString('hex')}`;}
function ichefOpsText(value='',max=5000){return String(value ?? '').trim().slice(0,max);}
function ichefOpsKey(value=''){return ichefStaffChatDeptKey(value);}

const ICHEF_OPS_SECTORS = Object.freeze([
{key:'cuisine',label:'Cuisine'},
{key:'service',label:'Service / Salle'},
{key:'bar',label:'Bar'},
{key:'hotel',label:'Hôtel'},
{key:'reception',label:'Réception'},
{key:'housekeeping',label:'Housekeeping / Étages'},
{key:'maintenance',label:'Maintenance'},
{key:'economat',label:'Économat'}
]);
function ichefOpsSectorKey(value=''){
const raw=ichefOpsKey(value);
const aliases={
cuisine:'cuisine',kitchen:'cuisine',
service:'service',salle:'service',serveur:'service',restaurant:'service',
bar:'bar',
hotel:'hotel',hotellerie:'hotel',
reception:'reception',front_office:'reception',frontoffice:'reception',accueil:'reception',
housekeeping:'housekeeping',etages:'housekeeping',etage:'housekeeping',menage:'housekeeping',linge:'housekeeping',
maintenance:'maintenance',technique:'maintenance',
economat:'economat',achats:'economat',achat:'economat',stocks:'economat',stock:'economat'
};
return aliases[raw] || (ICHEF_OPS_SECTORS.some(s=>s.key===raw)?raw:'economat');
}
function ichefOpsSectorLabel(value=''){
const key=ichefOpsSectorKey(value);
return ICHEF_OPS_SECTORS.find(s=>s.key===key)?.label || 'Économat';
}
// V239 — accès limité au département réel, indépendamment du droit de commander.
function ichef239IsMaster(auth={}){return String(auth?.claims?.staffId||'').startsWith('MASTER:');}
function ichef239InSector(auth={},sector='economat'){
 if(ichef239IsMaster(auth))return true;
 const self=ichefOpsSelf(auth);
 return Boolean(self.deptKey && ichefOpsSectorKey(self.deptKey)===ichefOpsSectorKey(sector));
}
function ichefOpsCanReceiveOrder(order={},auth={}){
 return ichef239InSector(auth,order.sectorKey||'economat');
}
// L'annuaire des collaborateurs RH est la source de vérité des affectations.
const ichef239PurchaseGrantSchema=new mongoose.Schema({
 tenantID:{type:String,required:true,index:true},staffId:{type:String,required:true},
 sectorKey:{type:String,required:true},canOrder:{type:Boolean,default:false},
 updatedBy:String,updatedAt:{type:Date,default:Date.now}
},{minimize:false});
ichef239PurchaseGrantSchema.index({tenantID:1,staffId:1,sectorKey:1},{unique:true});
const Ichef239PurchaseGrant=mongoose.models.Ichef239PurchaseGrant||mongoose.model('Ichef239PurchaseGrant',ichef239PurchaseGrantSchema);
function ichef239CanManageDepartment(auth={},sector='economat'){
 if(ichef239IsMaster(auth))return true;
 const role=ichefOpsRoleText(auth.staff||{});
 return /direction|directeur|directrice|gerant|gerante|manager|chef|responsable|superviseur|supervisor|admin/.test(role)&&ichef239InSector(auth,sector);
}
// V240 — Horaires de travail : un collaborateur connecté doit être pointé
// EN SERVICE dans STAFF_ACCESS. On n'accepte ni heure ni rôle fournis par le navigateur.
// Le pointage dure au maximum 16 h sans nouvelle entrée afin de ne jamais
// conserver accidentellement un accès d'achat après une session oubliée.
function ichef240DutyState(auth={}){
 if(ichef239IsMaster(auth))return {onDuty:true,reason:'DIRECTION'};
 const staff=auth.staff||{};
 if(staff.onDuty!==true)return {onDuty:false,reason:'POINTAGE_REQUIS'};
 const lastAt=Date.parse(String(staff.lastPunchAt||''));
 const age=Date.now()-lastAt;
 if(!Number.isFinite(lastAt)||age<0||age>16*60*60*1000)return {onDuty:false,reason:'POINTAGE_EXPIRE'};
 const punch=String(staff.lastPunchType||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
 if(punch&&!punch.includes('ENTREE')&&!punch.includes('IN'))return {onDuty:false,reason:'SORTIE_DE_SERVICE'};
 return {onDuty:true,reason:'EN_SERVICE'};
}
async function ichef240PurchaseRights(auth={},sector='economat'){
 if(!ichef239InSector(auth,sector))return false;
 if(ichef239IsMaster(auth)||ichef239CanManageDepartment(auth,sector))return true;
 const id=ichefOpsSelf(auth).id;
 if(!id)return false;
 const grant=await Ichef239PurchaseGrant.findOne({tenantID:auth.tenantID,staffId:id,sectorKey:ichefOpsSectorKey(sector)}).lean();
 return grant?.canOrder===true;
}
async function ichef239CanOrder(auth={},sector='economat'){
 if(!ichef239InSector(auth,sector))return false;
 // Conserve les droits du responsable sur Chef/Administration hors service.
 // Les collaborateurs DELEGUES restent bloqués hors de leur pointage.
 if(ichef239IsMaster(auth)||ichef239CanManageDepartment(auth,sector))return true;
 if(!ichef240DutyState(auth).onDuty)return false;
 const id=ichefOpsSelf(auth).id;if(!id)return false;
 const g=await Ichef239PurchaseGrant.findOne({tenantID:auth.tenantID,staffId:id,sectorKey:ichefOpsSectorKey(sector)}).lean();
 return g?.canOrder===true;
}
async function ichef239EnsureOrder(req,res,auth,sector){
 if(await ichef239CanOrder(auth,sector))return true;
 res.status(403).json({success:false,error:!ichef240DutyState(auth).onDuty?'Commande disponible uniquement pendant votre service, après pointage d’entrée.':'Commande réservée aux collaborateurs autorisés de votre département.'});return false;
}

function ichefOpsStaffId(item={}){return String(item?.id ?? item?.staffId ?? item?.employeeId ?? item?.rhId ?? item?.matricule ?? '').trim().slice(0,120);}
function ichefOpsStaffName(item={}){return ichefStaffChatMemberName(item) || 'Collaborateur';}
function ichefOpsRoleText(item={}){
const raw=[item?.role,item?.position,item?.poste,item?.fonction,item?.jobTitle,item?.title,item?.type,item?.profile,item?.department,item?.dept,item?.service,item?.team].filter(Boolean).join(' ');
return raw.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
}
function ichefOpsExplicitPermission(staff={},group='',key=''){
const p=staff?.permissions&&typeof staff.permissions==='object'?staff.permissions:{};
const g=p?.[group]&&typeof p[group]==='object'?p[group]:{};
if(typeof g?.[key]==='boolean')return g[key];
const flat=p?.[`${group}.${key}`];
if(typeof flat==='boolean')return flat;
return null;
}
function ichefOpsCapabilities(staff={}){
const role=ichefOpsRoleText(staff);
const taskManagerRole=/master|direction|directeur|directrice|gerant|gerante|manager|chef|responsable|superviseur|supervisor|rh|ressources humaines|admin/.test(role);
const purchaseCreatorRole=/master|direction|directeur|directrice|gerant|gerante|manager|chef|responsable|economat|achat|approvision|purchas|admin/.test(role);
const purchaseApproverRole=/master|direction|directeur|directrice|gerant|gerante|manager|economat|achat|approvision|admin/.test(role);
const a=ichefOpsExplicitPermission(staff,'tasks','manage');
const b=ichefOpsExplicitPermission(staff,'purchases','create');
const c=ichefOpsExplicitPermission(staff,'purchases','approve');
const d=ichefOpsExplicitPermission(staff,'suppliers','manage');
const manageTasks=a===null?taskManagerRole:a;
const createPurchases=b===null?purchaseCreatorRole:b;
const approvePurchases=c===null?purchaseApproverRole:c;
const manageSuppliers=d===null?purchaseApproverRole:d;
return {manageTasks,createSelfTasks:true,createPurchases,approvePurchases,viewPurchases:createPurchases||approvePurchases,manageSuppliers,viewSuppliers:createPurchases||approvePurchases||manageSuppliers};
}
function ichefOpsDirectory(auth={}){
const source=[...(Array.isArray(auth.staffAccess)?auth.staffAccess:[]),...ichefStaffPortalArray(auth.state?.activeOrders?.DIRECTORY_MASTER)];
const map=new Map();
for(const item of source){
if(!item||item.active===false)continue;
const id=ichefOpsStaffId(item);if(!id||map.has(id))continue;
const dept=ichefStaffChatMemberDept(item);
map.set(id,{id,name:ichefOpsStaffName(item),role:ichefStaffChatMemberRole(item),dept,deptKey:ichefStaffChatDeptKey(dept)});
}
return [...map.values()];
}
function ichefOpsSelf(auth={}){
const id=String(auth?.claims?.staffId||ichefOpsStaffId(auth?.staff)||'').trim();
const dept=ichefStaffChatMemberDept(auth?.staff||{});
return {id,name:ichefOpsStaffName(auth?.staff||{}),role:ichefStaffChatMemberRole(auth?.staff||{}),dept,deptKey:ichefStaffChatDeptKey(dept)};
}
function ichefOpsTaskCanView(task={},auth={}){
const caps=ichefOpsCapabilities(auth.staff||{});if(caps.manageTasks)return true;
const self=ichefOpsSelf(auth);
if(String(task.createdByStaffId||'')===self.id)return true;
if((task.assignedStaffIds||[]).some(id=>String(id)===self.id))return true;
if(self.deptKey&&(task.assignedTeamKeys||[]).some(k=>ichefOpsSectorKey(k)===ichefOpsSectorKey(self.deptKey)))return true;
return false;
}
function ichefOpsTaskCanWork(task={},auth={}){
const caps=ichefOpsCapabilities(auth.staff||{});if(caps.manageTasks)return true;
const self=ichefOpsSelf(auth);
if((task.assignedStaffIds||[]).some(id=>String(id)===self.id))return true;
if(self.deptKey&&(task.assignedTeamKeys||[]).some(k=>ichefOpsSectorKey(k)===ichefOpsSectorKey(self.deptKey)))return true;
return false;
}
function ichefOpsHistory(action,auth={},details={}){
const self=ichefOpsSelf(auth);
return {eventId:ichefOpsId('EVT'),action:ichefOpsText(action,80),staffId:self.id,staffName:self.name,details:details&&typeof details==='object'?details:{},createdAt:new Date()};
}
function ichefOpsOrderTotal(items=[]){return Math.round(items.reduce((sum,item)=>sum+(Number(item.quantity||0)*Number(item.unitPrice||0)),0)*100)/100;}
function ichefOpsPublicTask(row={}){
const x=row?.toObject?row.toObject():row;
return {id:String(x.taskId||''),title:String(x.title||''),description:String(x.description||''),priority:String(x.priority||'NORMAL'),status:String(x.status||'TODO'),assignedStaffIds:Array.isArray(x.assignedStaffIds)?x.assignedStaffIds:[],assignedTeamKeys:Array.isArray(x.assignedTeamKeys)?x.assignedTeamKeys:[],assignedTeamLabels:Array.isArray(x.assignedTeamLabels)?x.assignedTeamLabels:[],recurrence:String(x.recurrence||'NONE'),dueAt:x.dueAt||null,startedAt:x.startedAt||null,completedAt:x.completedAt||null,completedByName:String(x.completedByName||''),createdByStaffId:String(x.createdByStaffId||''),createdByName:String(x.createdByName||''),createdByRole:String(x.createdByRole||''),sourceType:String(x.sourceType||'MANUAL'),sourceRefId:String(x.sourceRefId||''),comments:Array.isArray(x.comments)?x.comments:[],history:Array.isArray(x.history)?x.history.slice(-40):[],createdAt:x.createdAt||null,updatedAt:x.updatedAt||null};
}
function ichefOpsEmitTask(tenantID,task,kind='updated'){
const packet={tenantID:cleanString(tenantID),taskId:String(task?.taskId||task?.id||''),kind,timestamp:new Date().toISOString()};
const room=ichefStaffRealtimeRoom(tenantID);if(room)io.to(room).emit('ops-task-changed',packet);
for(const staffId of(task?.assignedStaffIds||[])){const userRoom=ichefStaffUserRoom(tenantID,staffId);if(userRoom)io.to(userRoom).emit('ops-task-changed',packet);}
}
async function ichefOpsLoadAuthorizedSession(req){
let auth=await ichefLoadActiveStaffSession(req);
if(auth.ok)return auth;
const tenantID=cleanString(req.query?.tenantID||req.body?.tenantID||req.headers?.['x-ichef-tenant']);
const claims=ichefVerifySignedSession(ichefBearerToken(req),{tenantID,scope:'OPS_MASTER'});
if(!tenantID||claims?.role!=='MASTER')return auth;
const tokenDevice=String(claims.deviceId||'').trim();
const requestDevice=String(req.headers?.['x-ichef-device']||'').trim();
if(tokenDevice&&(!requestDevice||tokenDevice!==requestDevice))return {ok:false,tenantID,error:'Session Operations non reconnue sur cet appareil.'};
const tenant=await Tenant.findOne({tenantID},{tenantID:1,status:1,archivedAt:1}).lean();
if(!tenant||tenant.archivedAt||String(tenant.status||'').toUpperCase()!=='ACTIF')return {ok:false,tenantID,error:'Accès établissement suspendu.'};
const state=await AppState.findOne({tenantID});
const staffAccess=ichefStaffPortalArray(state?.activeOrders?.STAFF_ACCESS);
return {ok:true,tenantID,claims:{...claims,staffId:`MASTER:${tenantID}`},tenant,state,staffAccess,staff:{id:`MASTER:${tenantID}`,name:'Direction',role:'MASTER',dept:'DIRECTION',active:true,permissions:{tasks:{manage:true},purchases:{create:true,approve:true},suppliers:{manage:true}}}};
}
async function ichefOpsRequire(req,res,{purchaseView=false,purchaseCreate=false,purchaseApprove=false,supplierManage=false}={}){
const auth=await ichefOpsLoadAuthorizedSession(req);
if(!auth.ok){res.status(401).json({success:false,error:auth.error||'Session Operations invalide.'});return null;}
const caps=ichefOpsCapabilities(auth.staff||{});
if(purchaseView&&!caps.viewPurchases){res.status(403).json({success:false,error:'Accès achats fournisseurs non autorisé.'});return null;}
if(purchaseCreate&&!caps.createPurchases){res.status(403).json({success:false,error:'Création de commande fournisseur non autorisée.'});return null;}
if(purchaseApprove&&!caps.approvePurchases){res.status(403).json({success:false,error:'Validation de commande fournisseur non autorisée.'});return null;}
if(supplierManage&&!caps.manageSuppliers){res.status(403).json({success:false,error:'Gestion des fournisseurs non autorisée.'});return null;}
return {...auth,caps,self:ichefOpsSelf(auth)};
}


// ============================================================================
// V223 — DROITS HACCP STAFF. API isolée, session signée + appareil + tenant.
// Ne remplace pas les routes historiques /get-current-state et /update-order.
// Les routes historiques doivent être migrées avant revendication de sécurité globale.
// ============================================================================
const ICHEF_HACCP_223_SECTORS = ['CUISINE','PATISSERIE','BAR','SERVICE'];
const ICHEF_HACCP_223_DATA_TABLES = ['HACCP_TEMP','HACCP_CLEANING','HACCP_TRACE'];
const ichefHaccp223Schema=new mongoose.Schema({
 tenantID:{type:String,required:true,index:true},staffId:{type:String,required:true},
 sectors:{type:[String],default:[]},temporary:{type:[new mongoose.Schema({sector:String,expiresAt:Date},{_id:false})],default:[]},
 disabled:{type:Boolean,default:false},updatedBy:String,updatedAt:{type:Date,default:Date.now}
},{minimize:false});
ichefHaccp223Schema.index({tenantID:1,staffId:1},{unique:true});
const IchefHaccp223Grant=mongoose.models.IchefHaccp223Grant||mongoose.model('IchefHaccp223Grant',ichefHaccp223Schema);
function ichefHaccp223Dept(text=''){
 const s=String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase();
 if(/SERVICE|SALLE|SERVEUR|SERVEUSE|WAITER|RESTAURANT|CHEF DE RANG/.test(s))return 'SERVICE';
 if(/CUISINE|CUISINIER|COMMIS|KITCHEN|CHEF DE CUISINE|SOUS CHEF/.test(s))return 'CUISINE';
 if(/PATISSERIE|PATISSIER|PASTRY/.test(s))return 'PATISSERIE';
 if(/BAR|BARMAN|BARMAID/.test(s))return 'BAR';
 return '';
}
function ichefHaccp223Manager(auth){
 const id=String(auth?.claims?.staffId||'');
 const perm=auth?.staff?.permissions?.haccp?.manage===true || auth?.staff?.permissions?.['haccp.manage']===true;
 const named=/(RESPONSABLE\s*HACCP|SUPERVISEUR\s*HACCP)/i.test([auth?.staff?.role,auth?.staff?.position,auth?.staff?.fonction].join(' '));
 return id.startsWith('MASTER:') || ichefTerminalStaffIsManager(auth?.staff||{}) || perm || named;
}
function ichefHaccp223SelfId(auth){return String(auth?.claims?.staffId||auth?.staff?.id||'');}
async function ichefHaccp223Access(auth){
 const sid=ichefHaccp223SelfId(auth);
 if(ichefHaccp223Manager(auth))return {manager:true,sectors:[...ICHEF_HACCP_223_SECTORS],assigned:true};
 const grant=await IchefHaccp223Grant.findOne({tenantID:auth.tenantID,staffId:sid}).lean();
 if(grant?.disabled)return {manager:false,sectors:[],assigned:true};
 const base=grant?grant.sectors:[ichefHaccp223Dept(ichefStaffChatMemberDept(auth.staff)||auth.staff?.role||'')];
 const now=Date.now();
 const temporary=(grant?.temporary||[]).filter(x=>new Date(x?.expiresAt||0).getTime()>now).map(x=>x.sector);
 return {manager:false,sectors:[...new Set([...base,...temporary].filter(x=>ICHEF_HACCP_223_SECTORS.includes(x)))],assigned:!!grant};
}
async function ichefHaccp223Auth(req,res,{manager=false}={}){
 const auth=await ichefOpsLoadAuthorizedSession(req);
 if(!auth.ok){res.status(401).json({success:false,error:auth.error||'Session Staff non reconnue.'});return null;}
 const access=await ichefHaccp223Access(auth);
 if(manager&&!access.manager){res.status(403).json({success:false,error:'Réservé aux responsables HACCP.'});return null;}
 if(!manager&&!access.sectors.length){res.status(403).json({success:false,error:'Aucun secteur HACCP attribué. Contactez votre responsable.'});return null;}
 // V224 : toutes les API sectorisées passent cette vérification SERVEUR.
 // L'entrée MASTER reste un accès d'administration distinct.
 if(!String(auth?.claims?.staffId||'').startsWith('MASTER:')){
   const presence=await ichefHaccp224CheckPresence(req,auth);
   if(!presence.allowed){res.setHeader('Cache-Control','no-store');res.status(403).json({success:false,code:'HACCP_SITE_REQUIRED',error:'Accès HACCP suspendu : présence dans l’établissement non vérifiée.',presence});return null;}
 }
 return {...auth,haccp223:access};
}

// ============================================================================
// V224 — PRÉSENCE HACCP : accès par réseau d'établissement + tolérance 5 min.
// PILOTE INACTIF par défaut. Nécessite vérification de la chaîne proxy Render.
// Un navigateur ne peut PAS lire de façon fiable le SSID Wi-Fi : le serveur
// vérifie l'IP publique connue de l'établissement, via un proxy de confiance.
// Le pointage RH reste indépendant. Aucune IP de l'employé n'est enregistrée.
// ============================================================================
const ICHEF_HACCP_224_ENABLED=/^(1|true|yes|on)$/i.test(String(process.env.ICHEF_HACCP_V224_ENABLED||'false'));
const ICHEF_HACCP_224_GRACE_MS=5*60*1000;
let ICHEF_HACCP_224_SITES={};
try{const x=JSON.parse(String(process.env.ICHEF_HACCP_V224_TENANT_SITE_IPS||'{}'));if(x&&typeof x==='object'&&!Array.isArray(x))ICHEF_HACCP_224_SITES=x;}catch(e){console.warn('[HACCP V224] configuration des réseaux invalide');}
function ichefHaccp224AllowedIps(tenantID){
 const list=ICHEF_HACCP_224_SITES[String(tenantID||'')];
 return new Set((Array.isArray(list)?list:[]).map(x=>String(x).trim()).filter(x=>net.isIP(x)));
}
const ICHEF_HACCP_224_PROXY_CIDRS=String(process.env.ICHEF_HACCP_V224_TRUSTED_PROXY_CIDRS||'').split(',').map(x=>x.trim()).filter(Boolean);
const ichefHaccp224PresenceSchema=new mongoose.Schema({
 tenantID:{type:String,required:true,index:true},staffId:{type:String,required:true},
 deviceHash:{type:String,required:true},lastVerifiedAt:{type:Date,default:null},
 updatedAt:{type:Date,default:Date.now}
},{minimize:false});
ichefHaccp224PresenceSchema.index({tenantID:1,staffId:1,deviceHash:1},{unique:true});
ichefHaccp224PresenceSchema.index({updatedAt:1},{expireAfterSeconds:7*24*3600});
const IchefHaccp224Presence=mongoose.models.IchefHaccp224Presence||mongoose.model('IchefHaccp224Presence',ichefHaccp224PresenceSchema);
function ichefHaccp224Ip(ip){
 let x=String(ip||'').trim().replace(/^\[|\]$/g,'');
 if(x.startsWith('::ffff:')&&net.isIP(x.slice(7))===4)x=x.slice(7);
 return net.isIP(x)?x:'';
}
function ichefHaccp224TrustedPeer(peer){
 // Aucun wildcard ni confiance accordée à une adresse simplement déclarée
 // par le navigateur ; seules les plages des reverse-proxies configurés.
 const ip=ichefHaccp224Ip(peer);if(!ip)return false;
 return ICHEF_HACCP_224_PROXY_CIDRS.some(rule=>{
   const parts=rule.split('/'),base=ichefHaccp224Ip(parts[0]);if(!base||!net.isIP(ip)||net.isIP(ip)!==net.isIP(base))return false;
   if(parts.length===1)return ip===base;
   const bits=Number(parts[1]);const width=net.isIP(ip)===4?32:128;
   if(!Number.isInteger(bits)||bits<0||bits>width||bits<8)return false;
   function bytes(s){
     if(net.isIP(s)===4)return s.split('.').map(Number);
     const [left,right]=s.toLowerCase().split('::');
     const a=left?left.split(':'):[],b=right?right.split(':'):[];
     if(right===undefined&&a.length!==8)return null;
     const parts=right===undefined?a:[...a,...Array(8-a.length-b.length).fill('0'),...b];
     if(parts.length!==8)return null;
     return parts.flatMap(v=>[(parseInt(v||'0',16)>>8)&255,parseInt(v||'0',16)&255]);
   }
   const aa=bytes(ip),bb=bytes(base);if(!aa||!bb)return false;
   let left=bits;for(let k=0;k<aa.length;k++){
     if(left<=0)break;const take=Math.min(left,8),mask=(0xff<<(8-take))&255;
     if((aa[k]&mask)!==(bb[k]&mask))return false;left-=take;
   }
   return true;
 });
}
function ichefHaccp224ClientIp(req){
 const peer=ichefHaccp224Ip(req.socket?.remoteAddress);
 if(!peer)return '';
 if(ichefHaccp224TrustedPeer(peer)){
   // Le proxy DOIT ajouter l'adresse du client réel en dernier.
   // Exige configuration et tests d'anti-usurpation à la sortie Render.
   const list=String(req.headers['x-forwarded-for']||'').split(',').map(x=>x.trim()).filter(Boolean);
   if(!list.length)return '';
   return ichefHaccp224Ip(list[list.length-1]);
 }
 // Connexion directe : ne jamais utiliser un X-Forwarded-For non fiable.
 return peer;
}
function ichefHaccp224DeviceHash(req){
 const dev=String(req.headers['x-ichef-device']||'').trim();
 return dev&&dev.length<=255?nodeCrypto.createHash('sha256').update('HACCP-V224|'+dev).digest('hex'):'';
}
async function ichefHaccp224CheckPresence(req,auth){
 if(!ICHEF_HACCP_224_ENABLED)return {enabled:false,allowed:true,reason:'PILOTE_NON_ACTIVE',graceSeconds:300};
 const siteIps=ichefHaccp224AllowedIps(auth.tenantID);
 if(!siteIps.size)return {enabled:true,allowed:false,reason:'RESEAU_NON_CONFIGURE',graceSeconds:300};
 const staffId=ichefHaccp223SelfId(auth),deviceHash=ichefHaccp224DeviceHash(req);
 if(!staffId||!deviceHash)return {enabled:true,allowed:false,reason:'APPAREIL_NON_RECONNU',graceSeconds:300};
 const filter={tenantID:auth.tenantID,staffId,deviceHash},now=Date.now();
 const ip=ichefHaccp224ClientIp(req),onSite=ip&&siteIps.has(ip);
 if(onSite){
   await IchefHaccp224Presence.updateOne(filter,{$set:{lastVerifiedAt:new Date(now),updatedAt:new Date(now)}},{upsert:true});
   return {enabled:true,allowed:true,onSite:true,reason:'RESEAU_ETABLISSEMENT',expiresAt:new Date(now+ICHEF_HACCP_224_GRACE_MS).toISOString(),graceSeconds:300};
 }
 const old=await IchefHaccp224Presence.findOne(filter,{lastVerifiedAt:1}).lean();
 const ts=old?.lastVerifiedAt?new Date(old.lastVerifiedAt).getTime():0;
 const expiresAt=ts+ICHEF_HACCP_224_GRACE_MS;
 if(ts&&now<expiresAt)return {enabled:true,allowed:true,onSite:false,reason:'TOLERANCE_5_MINUTES',expiresAt:new Date(expiresAt).toISOString(),graceSeconds:300};
 return {enabled:true,allowed:false,onSite:false,reason:'HORS_ETABLISSEMENT',graceSeconds:300};
}
// Statut non sensible pour le portail : aucune donnée HACCP divulguée.
app.get('/api/staff/haccp/presence',async(req,res)=>{
 try{
  res.setHeader('Cache-Control','no-store');
  const auth=await ichefOpsLoadAuthorizedSession(req);
  if(!auth.ok)return res.status(401).json({success:false,error:'Session Staff invalide.'});
  const access=await ichefHaccp223Access(auth);
  if(!access.sectors.length)return res.status(403).json({success:false,hasSectors:false,error:'Aucun secteur HACCP autorisé.'});
  const presence=await ichefHaccp224CheckPresence(req,auth);
  return res.json({success:true,hasSectors:true,allowedSectors:access.sectors,manager:access.manager,...presence});
 }catch(err){console.warn('[HACCP V224 présence]',err?.message||err);return res.status(503).json({success:false,error:'Présence impossible à vérifier.'});}
});

function ichefHaccp223Subset(data=[],sectors=[]){
 const set=new Set(sectors);
 return (Array.isArray(data)?data:[]).filter(row=>set.has(String(row?.dept||'').trim().toUpperCase()));
}
function ichefHaccp223NodeData(state,key,fallback){
 const val=state?.activeOrders?.[key]?.data;
 return val===undefined?fallback:val;
}
app.get('/api/staff/haccp/context',async(req,res)=>{
 try{res.setHeader('Cache-Control','no-store');const a=await ichefHaccp223Auth(req,res);if(!a)return;
 return res.json({success:true,self:{id:ichefHaccp223SelfId(a),name:ichefOpsStaffName(a.staff),role:ichefStaffChatMemberRole(a.staff)},allowedSectors:a.haccp223.sectors,manager:a.haccp223.manager,explicitAssignment:a.haccp223.assigned,build:'HACCP-V223'});
 }catch(e){console.error('[HACCP V223 context]',e);return res.status(500).json({success:false,error:'Autorisation HACCP indisponible.'});}
});
app.get('/api/staff/haccp/state',async(req,res)=>{
 try{res.setHeader('Cache-Control','no-store');const a=await ichefHaccp223Auth(req,res);if(!a)return;
 const sectors=a.haccp223.sectors,st=a.state||await AppState.findOne({tenantID:a.tenantID}).lean();
 const lists=ichefHaccp223NodeData(st,'HACCP_LISTS_MASTER',{}),safeLists={};
 for(const sect of sectors)if(lists&&typeof lists[sect]==='object')safeLists[sect]=lists[sect];
 const origSettings=ichefHaccp223NodeData(st,'SETTINGS_MASTER',{});
 const settings={country:origSettings?.country||'',countryCode:origSettings?.countryCode||'',taxConfig:{country:origSettings?.taxConfig?.country||'',currency:origSettings?.taxConfig?.currency||''}};
 const activeOrders={SETTINGS_MASTER:{data:settings},HACCP_LISTS_MASTER:{data:safeLists}};
 for(const table of ICHEF_HACCP_223_DATA_TABLES)activeOrders[table]={data:ichefHaccp223Subset(ichefHaccp223NodeData(st,table,[]),sectors)};
 return res.json({success:true,tenantID:a.tenantID,activeOrders,allowedSectors:sectors});
 }catch(e){console.error('[HACCP V223 state]',e);return res.status(500).json({success:false,error:'Données HACCP momentanément indisponibles.'});}
});
// Contrôles HACCP ajoutés sans écraser les relevés de collègues / secteurs.
app.post('/api/staff/haccp/records',async(req,res)=>{
 try{res.setHeader('Cache-Control','no-store');const a=await ichefHaccp223Auth(req,res);if(!a)return;
 const table=String(req.body?.tableId||'').toUpperCase();
 if(!ICHEF_HACCP_223_DATA_TABLES.includes(table))return res.status(403).json({success:false,error:'Modification de cette table interdite depuis Staff.'});
 const incoming=req.body?.data;
 if(!Array.isArray(incoming)||incoming.length>1600)return res.status(400).json({success:false,error:'Format ou volume de relevés invalide.'});
 const sectors=new Set(a.haccp223.sectors);
 if(incoming.some(x=>!x||typeof x!=='object'||Array.isArray(x)||!sectors.has(String(x.dept||'').trim().toUpperCase())))return res.status(403).json({success:false,error:'Un relevé concerne un secteur non autorisé.'});
 // Garanties d'intégrité : append-only et identifiants uniques ; pas de suppression ni réécriture.
 const current=ichefHaccp223NodeData(a.state,table,[]);
 const stored=(Array.isArray(current)?current:[]);
 const identity=x=>String(x?.id??x?.recordId??'').trim();
 const byId=new Map(stored.map(x=>[identity(x),x]).filter(([id])=>id));
 const receivedIds=new Set();const newEntries=[];
 for(const row of incoming){
   const id=identity(row);
   if(!id||id.length>150||receivedIds.has(id))return res.status(409).json({success:false,error:'Identifiant de relevé invalide ou répété.'});
   receivedIds.add(id);
   const previous=byId.get(id);
   if(previous){
    if(JSON.stringify(previous)!==JSON.stringify(row))return res.status(409).json({success:false,error:'Un relevé existant ne peut pas être réécrit depuis Staff. Utilisez une rectification.'});
   }else{
    if(JSON.stringify(row).length>360000)return res.status(413).json({success:false,error:'Relevé trop volumineux.'});
    if(row.originalId){const orig=byId.get(String(row.originalId));if(!orig||!sectors.has(String(orig.dept||'').toUpperCase()))return res.status(403).json({success:false,error:'Rectification hors de votre secteur interdite.'});}
    newEntries.push({...row,staffId:ichefHaccp223SelfId(a),staffName:ichefOpsStaffName(a.staff),serverRecordedAt:new Date().toISOString()});
   }
 }
 // Évite les sauvegardes qui suppriment silencieusement un relevé du même secteur.
 if(stored.some(x=>sectors.has(String(x?.dept||'').toUpperCase())&&identity(x)&&!receivedIds.has(identity(x)))){
  return res.status(409).json({success:false,error:'Données modifiées sur un autre appareil. Actualisez avant de sauvegarder.'});
 }
 if(newEntries.length){
  const nodePath=`activeOrders.${table}.data`;
  await AppState.updateOne({tenantID:a.tenantID},{$push:{[nodePath]:{$each:newEntries}}});
  const room=ichefStaffRealtimeRoom(a.tenantID);if(room)io.to(room).emit('haccp-staff-changed',{tenantID:a.tenantID,tableId:table,sectors:[...sectors]});
 }
 return res.json({success:true,added:newEntries.length});
 }catch(e){console.error('[HACCP V223 records]',e);return res.status(500).json({success:false,error:'Enregistrement HACCP indisponible.'});}
});
app.get('/api/staff/haccp/manage',async(req,res)=>{
 try{res.setHeader('Cache-Control','no-store');const a=await ichefHaccp223Auth(req,res,{manager:true});if(!a)return;
 const people=ichefOpsDirectory(a),grants=await IchefHaccp223Grant.find({tenantID:a.tenantID}).lean();
 const byId=new Map(grants.map(g=>[g.staffId,g]));
 return res.json({success:true,sectors:ICHEF_HACCP_223_SECTORS,people:people.map(p=>({id:p.id,name:p.name,dept:p.dept,role:p.role,grant:byId.get(p.id)?{sectors:byId.get(p.id).sectors,temporary:byId.get(p.id).temporary,disabled:byId.get(p.id).disabled}:null}))});
 }catch(e){console.error('[HACCP V223 manage]',e);return res.status(500).json({success:false,error:'Gestion HACCP momentanément indisponible.'});}
});
app.put('/api/staff/haccp/manage/:staffId',async(req,res)=>{
 try{res.setHeader('Cache-Control','no-store');const a=await ichefHaccp223Auth(req,res,{manager:true});if(!a)return;
 const staffId=String(req.params.staffId||'').slice(0,120);const people=ichefOpsDirectory(a);
 if(!people.some(p=>p.id===staffId))return res.status(404).json({success:false,error:'Collaborateur non trouvé dans cet établissement.'});
 const sectors=req.body?.sectors;if(!Array.isArray(sectors)||sectors.some(x=>!ICHEF_HACCP_223_SECTORS.includes(x)))return res.status(400).json({success:false,error:'Secteurs invalides.'});
 const temporary=Array.isArray(req.body?.temporary)?req.body.temporary:[];
 if(temporary.length>4||temporary.some(x=>!ICHEF_HACCP_223_SECTORS.includes(x?.sector)||!Number.isFinite(Date.parse(x?.expiresAt))||Date.parse(x.expiresAt)<Date.now()||Date.parse(x.expiresAt)>Date.now()+30*86400000))return res.status(400).json({success:false,error:'Accès temporaire invalide (maximum 30 jours).'});
 await IchefHaccp223Grant.findOneAndUpdate({tenantID:a.tenantID,staffId},{$set:{sectors:[...new Set(sectors)],temporary,disabled:req.body?.disabled===true,updatedBy:ichefHaccp223SelfId(a),updatedAt:new Date()}},{upsert:true,new:true,setDefaultsOnInsert:true});
 return res.json({success:true,staffId,sectors:[...new Set(sectors)]});
 }catch(e){console.error('[HACCP V223 grant]',e);return res.status(500).json({success:false,error:'Attribution HACCP impossible.'});}
});
