orderChannel:['MEMO','PDF','WHATSAPP','EMAIL','PORTAL','MANUAL'].includes(String(req.body?.orderChannel||'MEMO').toUpperCase())?String(req.body?.orderChannel||'MEMO').toUpperCase():'MEMO',
